inline constexpr std::size_t kCaseFoldCount =
    sizeof(kCaseFoldTable) / sizeof(kCaseFoldTable[0]);

inline const CaseFoldEntry *findCaseFold(std::uint32_t codepoint)
{
    std::size_t low = 0;
    std::size_t high = kCaseFoldCount;
    while (low < high)
    {
        const std::size_t middle = low + (high - low) / 2;
        if (kCaseFoldTable[middle].codepoint < codepoint)
        {
            low = middle + 1;
        }
        else
        {
            high = middle;
        }
    }
    if (low < kCaseFoldCount && kCaseFoldTable[low].codepoint == codepoint)
    {
        return &kCaseFoldTable[low];
    }
    return nullptr;
}

